func loadLinkablePages(ctx context.Context, db *sql.DB, siteID uuid.UUID, limit int, logger *zap.Logger) ([]linkablePage, int, error) {
	rows, err := db.QueryContext(ctx, `
		SELECT name, url, COALESCE(title,'') AS title, COALESCE(meta_description,'') AS description
		FROM pages
		WHERE site_id = $1
		  AND status NOT IN ('deleted', 'archived')
		  AND COALESCE(url, '') <> ''
		ORDER BY COALESCE(nav_order,100) ASC, name ASC
		LIMIT $2`, siteID, limit+1)
	if err != nil { return nil, 0, fmt.Errorf("query pages: %w", err) }
	defer rows.Close()
	for rows.Next() { /* scan; skip empty url; humanise title fallback */ }
	if err := rows.Err(); err != nil {
		return nil, 0, fmt.Errorf("page list truncated by a row error: %w", err)
	}
	// over the cap: ask for the real total rather than reporting the limit+1 probe
	if len(pages) > limit { /* pages = pages[:limit]; SELECT count(*) for the true omitted figure, -1 if unreadable */ }
	return pages, omitted, nil
}

